$ErrorActionPreference='Stop';$root=$PSScriptRoot;$base='http://127.0.0.1:8090'
& (Join-Path $root 'Stop-GameBridge.ps1');& (Join-Path $root 'Start-Prototype.ps1') -NoGodot
Invoke-RestMethod "$base/session/reset" -Method Post|Out-Null;$commit=(git -C $root rev-parse --short HEAD).Trim()
$inputs=@('look around the room','wave at guillermo and whistle','how high is the window?','got to window and try to open it','close the window and look at the top of the desk','look through the drawers and see if there are any papers','read any letters i find','look at the top of the desk','investigate the coarse fibers','look at the dark discoloration','investigate the dark mark','investigate the dark mark','investigate the dark mark','carefully investigate the dark mark','examine the painting','try to open the safe','use the crowbar to open the safe','read the note','is there a fire?','sniff the chair','move through the study door','enter the study')
$path=Join-Path $root 'eval/pre_phase6_live_replay.jsonl';if(Test-Path $path){Remove-Item -LiteralPath $path};$rows=@();$overviewNotebook=$null
foreach($text in $inputs){$watch=[Diagnostics.Stopwatch]::StartNew();$response=Invoke-RestMethod "$base/action" -Method Post -ContentType 'application/json' -Body (@{text=$text}|ConvertTo-Json);$watch.Stop();if($text-eq'look around the room'){$overviewNotebook=(Invoke-RestMethod "$base/session/state").notebook};$sentenceCount=@([regex]::Matches([string]$response.narration,'[.!?](?:["”'']?\s|$)')).Count;$row=[ordered]@{turn=$rows.Count+1;running_commit=$commit;input=$text;status=$response.status;narration=$response.narration;sentences=$sentenceCount;words=@([regex]::Matches([string]$response.narration,"\b[\p{L}\p{N}'’-]+\b")).Count;roll_feedback=$(if($null-eq$response.roll_feedback){$null}else{$response.roll_feedback});location=$response.state.location.id;safe_open=$response.state.slice_state.safe_open;window_open=$response.state.slice_state.window_open;latency_seconds=[math]::Round($watch.Elapsed.TotalSeconds,4)};$rows+=[pscustomobject]$row;$row|ConvertTo-Json -Depth 12 -Compress|Add-Content -Encoding utf8 $path;Write-Host "$($row.turn): $text -> $($row.status) $($row.roll_feedback)"}
$telemetry=@(Get-Content (Join-Path $root 'eval/playtest_turns.jsonl')|Select-Object -Last $inputs.Count|ConvertFrom-Json);$overviewJson=$overviewNotebook|ConvertTo-Json -Depth 12;$summary=[ordered]@{generated_utc=[datetime]::UtcNow.ToString('o');running_commit=$commit;turns=$rows.Count;resolved=@($rows|Where-Object status -eq resolved).Count;clarifications=@($rows|Where-Object status -eq needs_clarification).Count;engine_rejections=@($rows|Where-Object status -eq engine_rejected).Count;overview_notebook_interpretation_leaks=$(if($overviewJson-match'dried blood|hemp cordage|ordinary fire'){1}else{0});gesture_dialogue_violations=@($rows|Where-Object{$_.input-match'^wave'-and$_.narration-match'(?i)ask|say|tell'}).Count;property_target_errors=@($rows|Where-Object{$_.input-match'^how high'-and$_.narration-notmatch'(?i)waist|height|sill'}).Count;partial_compound_executions=@($rows|Where-Object{$_.input-match'^close the window and'-and$_.status-ne'needs_clarification'}).Count;drawer_target_substitutions=@($rows|Where-Object{$_.input-match'drawers'-and$_.narration-notmatch'(?i)drawer'}).Count;internal_language_leaks=@($rows|Where-Object{$_.narration-match'(?i)harmless experiment|result category|mundane result|safe target|nothing consequential'}).Count;average_sentences=[math]::Round((($rows.sentences|Measure-Object -Average).Average),2);average_words=[math]::Round((($rows.words|Measure-Object -Average).Average),1);average_live_latency_seconds=[math]::Round((($rows.latency_seconds|Measure-Object -Average).Average),4);narrator_retries=@($telemetry|Where-Object retry_occurred).Count;fallbacks=@($telemetry|Where-Object fallback_used).Count};$summary|ConvertTo-Json -Depth 10|Set-Content -Encoding utf8 (Join-Path $root 'eval/pre_phase6_live_replay_summary.json');$summary|ConvertTo-Json -Depth 10
